create or replace function public.admin_categories_search(p_token text, p_search text default '', p_status text default '', p_vertical text default '') returns jsonb language plpgsql security definer set search_path to 'public','extensions' as $$ begin if public.admin_validate_session(p_token) is null then raise exception 'unauthorized'; end if; return coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'vertical',c.vertical::text,'slug',c.slug,'nameFa',c."nameFa",'nameTr',c."nameTr",'nameEn',c."nameEn",'nameAr',c."nameAr",'order',c."order",'isPublished',c."isPublished",'productCount',(select count(*) from public."Product" p where p."categoryId"=c.id)) order by c."order",c."nameFa") from public."Category" c where (coalesce(p_search,'')='' or c.slug ilike '%'||p_search||'%' or c."nameFa" ilike '%'||p_search||'%' or c."nameTr" ilike '%'||p_search||'%' or c."nameEn" ilike '%'||p_search||'%' or c."nameAr" ilike '%'||p_search||'%' or coalesce(c."descriptionFa",'') ilike '%'||p_search||'%' or coalesce(c."descriptionTr",'') ilike '%'||p_search||'%' or coalesce(c."descriptionEn",'') ilike '%'||p_search||'%' or coalesce(c."descriptionAr",'') ilike '%'||p_search||'%') and (coalesce(p_status,'')='' or (p_status='PUBLISHED' and c."isPublished") or (p_status='DRAFT' and not c."isPublished")) and (coalesce(p_vertical,'')='' or c.vertical::text=p_vertical)),'[]'::jsonb); end $$;

create or replace function public.admin_services_search(p_token text, p_search text default '', p_status text default '', p_vertical text default '') returns jsonb language plpgsql security definer set search_path to 'public','extensions' as $$ begin if public.admin_validate_session(p_token) is null then raise exception 'unauthorized'; end if; return coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'vertical',s.vertical::text,'slug',s.slug,'nameFa',s."nameFa",'nameTr',s."nameTr",'nameEn',s."nameEn",'nameAr',s."nameAr",'price',s.price,'priceIsFrom',s."priceIsFrom",'durationMinutes',s."durationMinutes",'requiresBooking',s."requiresBooking",'isPublished',s."isPublished",'bookingCount',(select count(*) from public."ServiceBooking" b where b."serviceId"=s.id),'createdAt',s."createdAt") order by s."createdAt" desc) from public."Service" s where (coalesce(p_search,'')='' or s.slug ilike '%'||p_search||'%' or s."nameFa" ilike '%'||p_search||'%' or s."nameTr" ilike '%'||p_search||'%' or s."nameEn" ilike '%'||p_search||'%' or s."nameAr" ilike '%'||p_search||'%') and (coalesce(p_status,'')='' or (p_status='PUBLISHED' and s."isPublished") or (p_status='DRAFT' and not s."isPublished")) and (coalesce(p_vertical,'')='' or s.vertical::text=p_vertical)),'[]'::jsonb); end $$;

create or replace function public.admin_pages_search(p_token text, p_search text default '', p_status text default '', p_nav text default '') returns jsonb language plpgsql security definer set search_path to 'public','extensions' as $$ begin if public.admin_validate_session(p_token) is null then raise exception 'unauthorized'; end if; return coalesce((select jsonb_agg(to_jsonb(p) order by p."navOrder",p."createdAt") from public."Page" p where (coalesce(p_search,'')='' or p.slug ilike '%'||p_search||'%' or p."titleFa" ilike '%'||p_search||'%' or p."titleTr" ilike '%'||p_search||'%' or p."titleEn" ilike '%'||p_search||'%' or p."titleAr" ilike '%'||p_search||'%' or p.template ilike '%'||p_search||'%') and (coalesce(p_status,'')='' or (p_status='PUBLISHED' and p."isPublished") or (p_status='DRAFT' and not p."isPublished")) and (coalesce(p_nav,'')='' or (p_nav='YES' and p."showInNav") or (p_nav='NO' and not p."showInNav"))),'[]'::jsonb); end $$;

create or replace function public.admin_media_search(p_token text, p_search text default '') returns jsonb language plpgsql security definer set search_path to 'public','extensions' as $$ begin if public.admin_validate_session(p_token) is null then raise exception 'unauthorized'; end if; return coalesce((select jsonb_agg(to_jsonb(m) order by m."createdAt" desc) from public."Media" m where coalesce(p_search,'')='' or m.url ilike '%'||p_search||'%' or coalesce(m."altFa",'') ilike '%'||p_search||'%' or coalesce(m."altTr",'') ilike '%'||p_search||'%' or coalesce(m."altEn",'') ilike '%'||p_search||'%' or coalesce(m."altAr",'') ilike '%'||p_search||'%'),'[]'::jsonb); end $$;
